B.DC=new A.ej("tidy","\uc8fc\ubcc0\uc815\ub9ac","Tidy Up","1\ubd84 \ub3d9\uc548 \uc7a0\uc790\ub9ac\uc640 \ucc45\uc0c1 \uc8fc\ubcc0\uc744 \uc815\ub9ac\ud558\uc138\uc694. \ub05d\ub098\uba74 \uc815\ub9ac\ub41c \ubaa8\uc2b5\uc744 \ud55c \uc7a5 \ucc0d\uc5b4 \ub0a8\uae41\ub2c8\ub2e4.","Spend one minute tidying your bed and desk. When you are done, take a photo of the tidy space.",1,B.tp,B.dm)
B.Fr=new A.nz(1,"read")
B.DB=new A.ej("stoic","\uba85\uc0c1\ub85d","Meditations","\uc624\ub298\uc758 \uad6c\uc808\uc744 \ucc9c\ucc9c\ud788 \uc138 \ubc88 \uc77d\uc73c\uc138\uc694. \ud55c \ubc88 \uc77d\uc744 \ub54c\ub9c8\ub2e4 \ubc84\ud2bc\uc744 \ub204\ub985\ub2c8\ub2e4.","Read today's passage slowly, three times. Tap once each time you finish reading.",3,B.Fr,B.dm)
B.tq=new A.nz(2,"timer")
B.DD=new A.ej("meditate","\uba85\uc0c1","Meditate","\ud3b8\ud558\uac8c \uc549\uc544 \uc18c\ub9ac\ub97c \ud2c0\uace0 \ud638\ud761\uc5d0 \uc9d1\uc911\ud558\uc138\uc694. 10\ubd84\uc774 \uc9c0\ub098\uba74 \uc644\ub8cc\ud560 \uc218 \uc788\uc5b4\uc694.","Sit comfortably, play a sound and focus on your breath. You can check it off after 10 minutes.",10,B.tq,B.dm)
